mapper.select:

inner join `user_tenant` utt on utt.`user_id` = ur.`id`
where utt.`admin` = 1 and utt.`tenant` = #{tenant}
limit 1


inner join `user_organization` uon on ur.`id` = uon.`user_id`
inner join `position` pn on uon.`position_id` = pn.`id`
where uon.`position_id` = #{positionId}


inner join `user_organization` uon on ur.`id` = uon.`user_id`
inner join `organization` ozn on uon.`organization_id` = ozn.`id`
where uon.`organization_id` = #{organizationId}

select ur.`id`, ur.`name`, ur.`email`, ur.`phone`, ur.`mobile`, ur.`avatar`, ur.`gender`, ur.`photograph_key`, ur.`remark`, ur.`username`, ur.`password`, ur.`admin`, ut.`enabled`, ur.`entry_date`, ur.`last_login_time`, ur.`last_login_address`, ur.`last_update_password_time`, ur.`extension`, ur.`deleted`, ur.`create_by`, ur.`create_time`, ur.`update_by`, ur.`update_time`, ur.`validity`,uon.`organization_id` `organizationId`,o.`name` `organizationName`,o.`parent_id` `organizationParentId`, urole.`id` `roleId`,r.`name` `roleName`,p.`id` `positionId`,p.`name` `positionName` from `user` ur left join `user_tenant` ut on ur.`id` = ut.`user_id` left join `user_role` urole on ur.`id` = urole.`user_id` left join `role` r on r.`id` = urole.`role_id` left join `user_organization` uon on uon.`user_id` = ur.`id` left join `organization` o on o.`id` = uon.`organization_id` and o.`tenant`=#{tenant} left join `position` p on p.`id` = uon.`position_id`
ut.`tenant` = #{tenant}
and (ur.`name` like concat('%',#{keyword},'%') or ur.`phone` like concat('%',#{keyword},'%'))
and urole.`role_id` in
#{roleId}

SELECT ur.`id`, ur.`name`, ur.`email`, ur.`phone`, ur.`mobile`, ur.`avatar`, ur.`gender`, ur.`photograph_key`, ur.`remark`, ur.`username`, ur.`password`, ur.`admin`, ut.`enabled`, ut.`work_status`, ur.`entry_date`, ur.`last_login_time`, ur.`last_login_address`, ur.`last_update_password_time`, ur.`extension`, ur.`deleted`, ur.`create_by`, ur.`create_time`, ur.`update_by`, ur.`update_time`, ur.`validity`, role_temp.`id` roleId, `role_temp`.`name` `roleName`, org_temp.appointment_id AS appointmentId, org_temp.appointment_name AS appointmentName, org_temp.organizationName, org_temp.organization_id AS organizationId, org_temp.position_id AS positionId, org_temp.positionName, ut.work_status FROM `user` ur JOIN `user_tenant` ut ON ur.`id` = ut.`user_id` LEFT JOIN ( SELECT r.id, urole.user_id, r.`name` FROM user_role urole LEFT JOIN role r ON r.id = urole.role_id WHERE r.`tenant` = #{tenant} ) role_temp ON role_temp.`user_id` = ur.`id` LEFT JOIN ( SELECT uon.user_id, uon.organization_id, o.`name` AS `organizationName`, uon.position_id, p.`name` AS `positionName`, uon.appointment_id, apm.`name` AS `appointment_name` FROM user_organization uon LEFT JOIN `organization` o ON o.`id` = uon.`organization_id` LEFT JOIN `position` p ON p.`id` = uon.`position_id`AND p.`tenant` = #{tenant} LEFT JOIN appointment apm ON apm.id = uon.appointment_id AND apm.tenant = #{tenant} WHERE o.`tenant` = #{tenant} ) org_temp ON org_temp.user_id = ur.id where ut.`tenant` = #{tenant} and `ur`.`deleted` = 0
and ut.`enabled` = #{query.enabled} and ur.`enabled` = #{query.enabled}
and ur.`name` like concat('%', #{query.keyword}, '%')
and ur.`id` in
#{id}
and role_temp.`id` in
#{id}
and ur.`username` in
#{username}
and ur.`mobile` in
#{mobile}
and org_temp.`appointment_id` in
#{id}
and org_temp.`position_id` in
#{id}
and org_temp.`organization_id` in
#{id}

