select ur.`id`, ur.`name`, ur.`email`, ur.`phone`, ur.`mobile`, ur.`avatar`, ur.`gender`, ur.`photograph_key`, ur.`remark`, ur.`username`, ur.`password`, ur.`admin`, ut.`enabled`, ur.`entry_date`, ur.`last_login_time`, ur.`last_login_address`, ur.`last_update_password_time`, ur.`extension`, ur.`deleted`, ur.`create_by`, ur.`create_time`, ur.`update_by`, ur.`update_time`, ur.`validity` ,uon.`organization_id` `organizationId`,o.`name` `organizationName`,o.`parent_id` `organizationParentId`, urole.`id` `roleId`,r.`name` `roleName`,p.`id` `positionId`,p.`name` `positionName` from `user` ur left join `user_tenant` ut on ur.`id` = ut.`user_id` left join `user_role` urole on ur.`id` = urole.`user_id` left join `role` r on r.`id` = urole.`role_id` left join `user_organization` uon on uon.`user_id` = ur.`id` left join `organization` o on o.`id` = uon.`organization_id` and o.`tenant`=#{query.tenant} left join `position` p on p.`id` = uon.`position_id` where ut.`tenant` = #{query.tenant}
