GROUP BY ur.`id`

select DISTINCT `u`.* from `user` `u`
inner join `user_tenant` `ut` on u.`id` = `ut`.`user_id` and `ut`.`admin` = #{query.isAdmin}
and ( `u`.`name` like concat('%',#{query.keyword},'%') or `u`.mobile like concat('%',#{query.keyword},'%') )
and `u`.`gender` = #{query.gender}
and `u`.`enabled` = #{query.enabled}
order by `u`.`create_time` desc
